class ListNode<K, V> {
  key: K;
  value: V;
  prev: ListNode<K, V> | null = null;
  next: ListNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LRUCache<K = number, V = number> {
  private capacity: number;
  private map: Map<K, ListNode<K, V>>;
  private head: ListNode<K, V>;
  private tail: ListNode<K, V>;

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.map = new Map<K, ListNode<K, V>>();
    // Sentinel nodes to simplify edge cases.
    this.head = new ListNode<K, V>(null as unknown as K, null as unknown as V);
    this.tail = new ListNode<K, V>(null as unknown as K, null as unknown as V);
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  private remove(node: ListNode<K, V>): void {
    const prev = node.prev!;
    const next = node.next!;
    prev.next = next;
    next.prev = prev;
    node.prev = null;
    node.next = null;
  }

  private addToFront(node: ListNode<K, V>): void {
    const first = this.head.next!;
    node.prev = this.head;
    node.next = first;
    this.head.next = node;
    first.prev = node;
  }

  private moveToFront(node: ListNode<K, V>): void {
    this.remove(node);
    this.addToFront(node);
  }

  get(key: K): V | -1 {
    const node = this.map.get(key);
    if (!node) {
      return -1;
    }
    this.moveToFront(node);
    return node.value;
  }

  put(key: K, value: V): void {
    const existing = this.map.get(key);
    if (existing) {
      existing.value = value;
      this.moveToFront(existing);
      return;
    }

    if (this.map.size >= this.capacity) {
      const lru = this.tail.prev!;
      if (lru !== this.head) {
        this.remove(lru);
        this.map.delete(lru.key);
      }
    }

    const node = new ListNode<K, V>(key, value);
    this.addToFront(node);
    this.map.set(key, node);
  }

  get size(): number {
    return this.map.size;
  }
}

// ----------------------------- Test Suite -----------------------------

function runTests(): void {
  // Basic get/put
  {
    const cache = new LRUCache<number, number>(2);
    cache.put(1, 100);
    cache.put(2, 200);
    console.assert(cache.get(1) === 100, "basic: get existing key 1 should be 100");
    console.assert(cache.get(2) === 200, "basic: get existing key 2 should be 200");
    console.assert(cache.get(3) === -1, "basic: missing key 3 should be -1");
    console.assert(cache.size === 2, "basic: size should be 2");
  }

  // Capacity eviction (least recently used evicted)
  {
    const cache = new LRUCache<number, number>(2);
    cache.put(1, 1);
    cache.put(2, 2);
    cache.put(3, 3); // evicts key 1
    console.assert(cache.get(1) === -1, "eviction: key 1 should be evicted");
    console.assert(cache.get(2) === 2, "eviction: key 2 should remain");
    console.assert(cache.get(3) === 3, "eviction: key 3 should be present");
    console.assert(cache.size === 2, "eviction: size should stay at capacity 2");
  }

  // Access-order update (get refreshes recency)
  {
    const cache = new LRUCache<number, number>(2);
    cache.put(1, 1);
    cache.put(2, 2);
    console.assert(cache.get(1) === 1, "access-order: get key 1 to refresh");
    cache.put(3, 3); // should evict key 2, not key 1
    console.assert(cache.get(2) === -1, "access-order: key 2 should be evicted");
    console.assert(cache.get(1) === 1, "access-order: key 1 should remain after refresh");
    console.assert(cache.get(3) === 3, "access-order: key 3 should be present");
  }

  // Overwrite existing key
  {
    const cache = new LRUCache<number, number>(2);
    cache.put(1, 1);
    cache.put(1, 10); // overwrite value
    console.assert(cache.get(1) === 10, "overwrite: value for key 1 should be 10");
    console.assert(cache.size === 1, "overwrite: size should remain 1");

    cache.put(2, 2);
    cache.put(1, 100); // overwrite also refreshes recency
    cache.put(3, 3); // evicts key 2 (least recently used)
    console.assert(cache.get(2) === -1, "overwrite: key 2 should be evicted");
    console.assert(cache.get(1) === 100, "overwrite: key 1 should hold latest value 100");
    console.assert(cache.get(3) === 3, "overwrite: key 3 should be present");
  }

  console.log("All LRUCache tests passed.");
}

runTests();
